CREATE OR REPLACE FUNCTION public.notice_window_open(_at timestamptz DEFAULT now(), _zone text DEFAULT 'Asia/Kolkata') RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT (_at AT TIME ZONE _zone)::time >= time '09:00' AND (_at AT TIME ZONE _zone)::time < time '20:00' $$;
CREATE OR REPLACE FUNCTION public.next_notice_open(_at timestamptz DEFAULT now(), _zone text DEFAULT 'Asia/Kolkata') RETURNS timestamptz LANGUAGE sql STABLE SET search_path=public AS $$ SELECT CASE WHEN (_at AT TIME ZONE _zone)::time < time '09:00' THEN (date_trunc('day',_at AT TIME ZONE _zone)+interval '9 hours') AT TIME ZONE _zone WHEN (_at AT TIME ZONE _zone)::time >= time '20:00' THEN (date_trunc('day',_at AT TIME ZONE _zone)+interval '1 day 9 hours') AT TIME ZONE _zone ELSE _at END $$;
REVOKE ALL ON FUNCTION public.notice_window_open(timestamptz,text),public.next_notice_open(timestamptz,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.notice_window_open(timestamptz,text),public.next_notice_open(timestamptz,text) TO authenticated,service_role;
CREATE TABLE public.deferred_listing_notices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),post_id uuid REFERENCES public.posts(id) ON DELETE CASCADE,matched_post_id uuid REFERENCES public.posts(id) ON DELETE CASCADE,message text NOT NULL,notice_mode text NOT NULL,available_at timestamptz NOT NULL,processed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.deferred_listing_notices TO service_role; ALTER TABLE public.deferred_listing_notices ENABLE ROW LEVEL SECURITY; CREATE INDEX deferred_listing_notices_pending ON public.deferred_listing_notices(available_at) WHERE processed_at IS NULL;
CREATE OR REPLACE FUNCTION public.paid_alert_ready(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_paid_bell(_user) $$;
CREATE OR REPLACE FUNCTION public.can_notify(_uid uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE pref public.notification_preferences; zone text; local_now timestamp; used integer; cap integer; BEGIN IF _uid IS NULL OR NOT public.has_paid_bell(_uid) THEN RETURN false; END IF; SELECT * INTO pref FROM public.notification_preferences WHERE user_id=_uid; zone:=coalesce(pref.timezone,'Asia/Kolkata'); local_now:=now() AT TIME ZONE zone; IF pref.enabled=false OR NOT public.notice_window_open(now(),zone) THEN RETURN false; END IF; IF pref.quiet_start IS NOT NULL AND ((pref.quiet_start<pref.quiet_end AND local_now::time>=pref.quiet_start AND local_now::time<pref.quiet_end) OR (pref.quiet_start>pref.quiet_end AND (local_now::time>=pref.quiet_start OR local_now::time<pref.quiet_end))) THEN RETURN false; END IF; cap:=least(coalesce(pref.daily_limit,5),5); SELECT count(*) INTO used FROM public.notifications WHERE user_id=_uid AND created_at>=date_trunc('day',local_now) AT TIME ZONE zone; RETURN used<cap; END $$;
CREATE OR REPLACE FUNCTION public.guard_prime99_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE zone text; mode text:=coalesce(current_setting('app.bell_notice',true),''); BEGIN IF NOT public.has_paid_bell(NEW.user_id) OR EXISTS(SELECT 1 FROM public.notification_preferences WHERE user_id=NEW.user_id AND NOT enabled) THEN RETURN NULL; END IF; SELECT timezone INTO zone FROM public.notification_preferences WHERE user_id=NEW.user_id; zone:=coalesce(zone,'Asia/Kolkata'); IF NOT public.notice_window_open(now(),zone) THEN IF NOT EXISTS(SELECT 1 FROM public.deferred_listing_notices WHERE user_id=NEW.user_id AND post_id IS NOT DISTINCT FROM NEW.post_id AND matched_post_id IS NOT DISTINCT FROM NEW.matched_post_id AND message=NEW.message AND processed_at IS NULL) THEN INSERT INTO public.deferred_listing_notices(user_id,post_id,matched_post_id,message,notice_mode,available_at) VALUES(NEW.user_id,NEW.post_id,NEW.matched_post_id,NEW.message,mode,public.next_notice_open(now(),zone)); END IF; RETURN NULL; END IF; IF NOT public.can_notify(NEW.user_id) THEN RETURN NULL; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.work_occupation(_value text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE lower(trim(coalesce(_value,''))) WHEN 'డ్రైవర్' THEN 'driver' WHEN 'డ్రైవరు' THEN 'driver' WHEN 'ప్లంబర్' THEN 'plumber' WHEN 'ఎలక్ట్రిషియన్' THEN 'electrician' WHEN 'electrition' THEN 'electrician' ELSE lower(trim(coalesce(_value,''))) END $$;
CREATE OR REPLACE FUNCTION public.work_posts_match(a public.posts,b public.posts) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT a.module='job' AND b.module='job' AND a.user_id<>b.user_id AND a.status='active' AND b.status='active' AND a.service_type=b.service_type AND ((a.kind='seeker' AND b.kind='employer') OR (a.kind='employer' AND b.kind='seeker')) AND public.work_occupation(a.skill)<>'' AND public.work_occupation(a.skill)=public.work_occupation(b.skill) AND (a.area_scope='country' OR b.area_scope='country' OR lower(trim(a.location))='ఏ ప్రాంతమైనా' OR lower(trim(b.location))='ఏ ప్రాంతమైనా' OR (trim(coalesce(a.location,''))<>'' AND lower(trim(a.location))=lower(trim(b.location)))) $$;
REVOKE ALL ON FUNCTION public.work_occupation(text),public.work_posts_match(public.posts,public.posts) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.work_occupation(text),public.work_posts_match(public.posts,public.posts) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.guard_new_match_notifications() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mode text:=current_setting('app.bell_notice',true); BEGIN IF NEW.post_id IS NULL AND NEW.matched_post_id IS NULL THEN RETURN NEW; END IF; IF mode IS NULL OR mode NOT IN('owner','interest','automatic') THEN RETURN NULL; END IF; IF EXISTS(SELECT 1 FROM public.posts WHERE id IN(NEW.post_id,NEW.matched_post_id) AND (visible_after>now() OR job_expires_at<=now() OR status<>'active' OR NOT public.account_allowed(user_id))) THEN RETURN NULL; END IF; IF mode='automatic' AND NOT EXISTS(SELECT 1 FROM public.posts a JOIN public.posts b ON b.id=NEW.matched_post_id WHERE a.id=NEW.post_id AND a.user_id=NEW.user_id AND public.work_posts_match(a,b) AND public.has_paid_bell(a.user_id) AND public.has_paid_bell(b.user_id)) THEN RETURN NULL; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.match_post() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.posts; previous text:=coalesce(current_setting('app.bell_notice',true),''); BEGIN IF NEW.module<>'job' OR NEW.visible_after>now() OR NEW.job_expires_at<=now() OR NOT public.has_paid_bell(NEW.user_id) THEN RETURN NEW; END IF; PERFORM set_config('app.bell_notice','automatic',true); FOR m IN SELECT DISTINCT ON(p.user_id) p.* FROM public.posts p WHERE public.work_posts_match(NEW,p) AND public.has_paid_bell(p.user_id) AND (p.visible_after IS NULL OR p.visible_after<=now()) AND (p.job_expires_at IS NULL OR p.job_expires_at>now()) ORDER BY p.user_id,p.created_at DESC LIMIT 100 LOOP PERFORM 1 FROM public.profiles WHERE id=m.user_id FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.notifications WHERE user_id=m.user_id AND post_id=m.id AND matched_post_id=NEW.id) THEN INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(m.user_id,m.id,NEW.id,'మీ పని లేదా సేవకు సరిపోలే ప్రకటన వచ్చింది; ప్రకటన గంట ద్వారా స్పందించండి.'); END IF; END LOOP; PERFORM set_config('app.bell_notice',previous,true); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.dispatch_visible_post_matches() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; m public.posts; q public.deferred_listing_notices; n integer:=0; previous text:=coalesce(current_setting('app.bell_notice',true),''); BEGIN FOR p IN SELECT * FROM public.posts WHERE visible_after<=now() AND visibility_notified_at IS NULL AND status='active' AND (job_expires_at IS NULL OR job_expires_at>now()) ORDER BY visible_after LIMIT 20 FOR UPDATE SKIP LOCKED LOOP IF p.module='job' AND public.has_paid_bell(p.user_id) THEN PERFORM set_config('app.bell_notice','automatic',true); FOR m IN SELECT DISTINCT ON(c.user_id) c.* FROM public.posts c WHERE public.work_posts_match(p,c) AND public.has_paid_bell(c.user_id) AND (c.visible_after IS NULL OR c.visible_after<=now()) AND (c.job_expires_at IS NULL OR c.job_expires_at>now()) ORDER BY c.user_id,c.created_at DESC LIMIT 100 LOOP IF NOT EXISTS(SELECT 1 FROM public.notifications WHERE user_id=m.user_id AND post_id=m.id AND matched_post_id=p.id) THEN INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(m.user_id,m.id,p.id,'మీ పని లేదా సేవకు సరిపోలే ప్రకటన వచ్చింది; ప్రకటన గంట ద్వారా స్పందించండి.'); END IF; END LOOP; END IF; UPDATE public.posts SET visibility_notified_at=now() WHERE id=p.id; n:=n+1; END LOOP; FOR q IN SELECT * FROM public.deferred_listing_notices WHERE processed_at IS NULL AND available_at<=now() ORDER BY available_at LIMIT 100 FOR UPDATE SKIP LOCKED LOOP IF public.can_notify(q.user_id) THEN PERFORM set_config('app.bell_notice',q.notice_mode,true); INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(q.user_id,q.post_id,q.matched_post_id,q.message); UPDATE public.deferred_listing_notices SET processed_at=now() WHERE id=q.id; ELSIF NOT public.has_paid_bell(q.user_id) OR EXISTS(SELECT 1 FROM public.notification_preferences WHERE user_id=q.user_id AND NOT enabled) THEN UPDATE public.deferred_listing_notices SET processed_at=now() WHERE id=q.id; END IF; END LOOP; PERFORM set_config('app.bell_notice',previous,true); RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _other=public.support_admin_id() OR public.has_role(auth.uid(),'admin') THEN true WHEN NOT public.has_paid_bell(auth.uid()) THEN false WHEN _post IS NULL THEN EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.messages WHERE post_id IS NULL AND ((sender_id=auth.uid() AND receiver_id=_other) OR (receiver_id=auth.uid() AND sender_id=_other))) ELSE EXISTS(SELECT 1 FROM public.post_chat_pairs WHERE post_id=_post AND ((member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) END $$;
CREATE OR REPLACE FUNCTION public.enforce_paid_chat_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_post_chat(NEW.post_id,NEW.receiver_id) AND NOT public.has_role(NEW.sender_id,'admin') THEN RAISE EXCEPTION 'PAID_CHAT_OR_PRIVATE_PAIR_REQUIRED'; END IF; RETURN NEW; END $$; CREATE TRIGGER paid_chat_message_guard BEFORE INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.enforce_paid_chat_message();
CREATE OR REPLACE FUNCTION public.guard_post_delay() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.visible_after:=CASE WHEN public.has_paid_bell(NEW.user_id) THEN now() ELSE now()+interval '5 hours' END; ELSIF NEW.visible_after IS DISTINCT FROM OLD.visible_after AND coalesce(current_setting('app.post_review',true),'')<>'1' THEN RAISE EXCEPTION 'POST_DELAY_PROTECTED'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.release_paid_pending_posts() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='approved' AND OLD.status='pending' AND NEW.payment_purpose='membership' AND NEW.payable_amount=100 THEN PERFORM set_config('app.post_review','1',true); UPDATE public.posts SET visible_after=now(),visibility_notified_at=NULL WHERE user_id=NEW.user_id AND status='active' AND visible_after>now(); END IF; RETURN NEW; END $$; CREATE TRIGGER release_paid_pending_posts AFTER UPDATE ON public.prime99_payments FOR EACH ROW EXECUTE FUNCTION public.release_paid_pending_posts();
CREATE OR REPLACE FUNCTION public.claim_push_deliveries() RETURNS SETOF public.push_deliveries LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.push_deliveries SET status='processing',attempts=attempts+1,updated_at=now(),available_at=now()+interval '5 minutes' WHERE id IN(SELECT d.id FROM public.push_deliveries d LEFT JOIN public.notification_preferences p ON p.user_id=d.user_id WHERE d.status IN('pending','processing') AND d.available_at<=now() AND d.attempts<5 AND public.notice_window_open(now(),coalesce(p.timezone,'Asia/Kolkata')) ORDER BY d.available_at FOR UPDATE OF d SKIP LOCKED LIMIT 20) RETURNING * $$;